"use client"
import React from "react";
import StatButton from "./StatButton";
import { useEffect, useState } from "react";

function StatButtonContainer({ label, endpoint } : {label : string, endpoint: string}){

    const [stats, setStats] = useState<string[]>([]);
    const selectedStats: Record<string, object> = {}

    function handleSelect(stat: string, value: string){
        if (stat in selectedStats){
            selectedStats[stat] = {"selected" : !selectedStats[stat], "value": value} 
        } else {
            selectedStats[stat] = {"selected":true, "value": "0"};
        }

        console.log(selectedStats)
    }

    useEffect(() => {

        async function loadHome() {
            try {
                const res = await fetch(`http://localhost:5000${endpoint}`)
                const data = await res.json()
                setStats(data);
                console.log(data)
            } catch (e) {
                console.log(`Error fetching at home ${e}`)
            }
        }
        loadHome();
    }, []);

    return(
        <div className="flex items-center justify-center flex-col gap-2">
            <h1 className="font-bold text-xl">{label}</h1>
            <div className="flex flex-row gap-4 flex-wrap items-center justify-center w-4/5 py-4 px-4 bg-[#051122] rounded-sm">
                {stats.map((stat, index) => (
                    <StatButton 
                    key={index} 
                    label={stat} 
                    onSelect={handleSelect}></StatButton>
                ))}
            </div>
        </div>

    )
}

export default StatButtonContainer;