"use client"

function Btn({label, action} : {label: string, action: () => void} ){
    return (
        <>
            <div onClick={action} className="items-center justify-center p-2 rounded-sm bg-[#4e55e3] text-white hover:cursor-pointer hover:text-white hover:bg-[#0d1826]">
                <p>{label}</p>
            </div>
        </>
    );
}

export default Btn;