"use client"
import { useEffect, useState } from "react";
import React from "react";

function StatButton({ label, onSelect } : { label: string, onSelect: (label: string, value: string) => void }){

    const [statState, setStatState] = useState<boolean>(false);

    return(
        <div className={`flex flex-col items-center justify-center hover:cursor-pointer rounded-sm ${statState ?  "bg-[#4e55e3] p-2 text-white" : "hover:bg-[#4e55e3] bg-[#0d1826] p-2 text-white"}`}>
            <p onClick={(event) => {
                    setStatState(!statState);
                    onSelect(label, "0");
                }
            }>{label}</p>
            <input type="text" defaultValue="0" onChange={(event) => onSelect(label, event.currentTarget.value)} size={1} className={` ${statState ? "flex text-center border border-solid rounded-sm w-full min-w-0 text-sm" : "hidden" }`} />
        </div>
    )
}

export default StatButton;